  Option::Some(value) => value,
  Option::None => 0,
 };
 match outcome {
  Result::Ok(value) => value,
  Result::Err(reason) => 0,
 };
 for value in values {
  if flag { continue; }
  break;
 }
 match maybe { _ => 0 };
}

